import XCTest
@testable import DJAnthemMapper

// PHASE_4C2A_MULTI_REGION_GEOMETRY_TESTS
final class MultiRegionWaveformGeometryTests: XCTestCase {
    private let accuracy = 0.000_001
    private func item(id: UUID = UUID(), start: TimeInterval?, end: TimeInterval?) -> AnthemRegionItem { AnthemRegionItem(id: id, region: AnthemRegion(start: start, end: end)) }
    private func geometry(regions: [AnthemRegionItem], activeRegionID: UUID, start: TimeInterval = 10, duration: TimeInterval = 10, width: Double = 1000) -> [MultiRegionWaveformGeometry.RegionGeometry] { MultiRegionWaveformGeometry.layout(regions: regions, activeRegionID: activeRegionID, viewport: WaveformViewport(start: start, duration: duration, width: width)) }
    private func assertEqual(_ actual: Double?, _ expected: Double, file: StaticString = #filePath, line: UInt = #line) { guard let actual else { XCTFail("Expected \(expected), found nil", file: file, line: line); return }; XCTAssertEqual(actual, expected, accuracy: accuracy, file: file, line: line) }

    func testThreeRegionsRemainSeparate() { let a=item(start:10,end:20), b=item(start:30,end:40), c=item(start:50,end:60); let r=geometry(regions:[a,b,c],activeRegionID:a.id,start:0,duration:100); XCTAssertEqual(r.count,3); XCTAssertEqual(r.map(\.id),[a.id,b.id,c.id]) }
    func testFullyVisibleRegion() { let a=item(start:12,end:18); let g=geometry(regions:[a],activeRegionID:a.id)[0]; assertEqual(g.startX,200); assertEqual(g.endX,800); assertEqual(g.shadeX,200); assertEqual(g.shadeWidth,600) }
    func testLeftClippedRegion() { let a=item(start:5,end:15); let g=geometry(regions:[a],activeRegionID:a.id)[0]; XCTAssertNil(g.startX); assertEqual(g.endX,500); assertEqual(g.shadeX,0); assertEqual(g.shadeWidth,500) }
    func testRightClippedRegion() { let a=item(start:15,end:25); let g=geometry(regions:[a],activeRegionID:a.id)[0]; assertEqual(g.startX,500); XCTAssertNil(g.endX); assertEqual(g.shadeX,500); assertEqual(g.shadeWidth,500) }
    func testRegionSpanningEntireViewport() { let a=item(start:5,end:25); let g=geometry(regions:[a],activeRegionID:a.id)[0]; XCTAssertNil(g.startX); XCTAssertNil(g.endX); assertEqual(g.shadeX,0); assertEqual(g.shadeWidth,1000) }
    func testRegionsEntirelyOffscreenHaveNoVisibleGeometry() { for a in [item(start:0,end:5),item(start:25,end:30)] { let g=geometry(regions:[a],activeRegionID:a.id)[0]; XCTAssertNil(g.startX); XCTAssertNil(g.endX); XCTAssertNil(g.shadeX); XCTAssertNil(g.shadeWidth) } }
    func testOverlappingRegionsRemainIndependent() { let a=item(start:10,end:20), b=item(start:15,end:25); let r=geometry(regions:[a,b],activeRegionID:a.id,start:10,duration:20); XCTAssertEqual(r.map(\.id),[a.id,b.id]); XCTAssertTrue(r[0].hasVisibleShading); XCTAssertTrue(r[1].hasVisibleShading) }
    func testExactlyOneMatchingRegionIsActive() { let a=item(start:10,end:20),b=item(start:30,end:40),c=item(start:50,end:60); let r=geometry(regions:[a,b,c],activeRegionID:b.id,start:0,duration:100); XCTAssertFalse(r[0].isActive); XCTAssertTrue(r[1].isActive); XCTAssertFalse(r[2].isActive) }
    func testChangingActiveRegionDoesNotChangeCoordinates() { let a=item(start:10,end:20),b=item(start:30,end:40); let x=geometry(regions:[a,b],activeRegionID:a.id,start:0,duration:100), y=geometry(regions:[a,b],activeRegionID:b.id,start:0,duration:100); for i in x.indices { XCTAssertEqual(x[i].startX,y[i].startX); XCTAssertEqual(x[i].endX,y[i].endX); XCTAssertEqual(x[i].shadeX,y[i].shadeX); XCTAssertEqual(x[i].shadeWidth,y[i].shadeWidth) }; XCTAssertTrue(x[0].isActive); XCTAssertTrue(y[1].isActive) }
    func testIncompleteRegionsHaveNoShading() { let a=item(start:12,end:nil),b=item(start:nil,end:18),c=item(start:13,end:17); let r=geometry(regions:[a,b,c],activeRegionID:c.id); XCTAssertNil(r[0].shadeX); XCTAssertNil(r[1].shadeX); XCTAssertTrue(r[2].hasVisibleShading) }
    func testInvalidRegionsHaveNoShading() { let rs=[item(start:15,end:15),item(start:18,end:12),item(start:-2,end:5),item(start:.nan,end:15),item(start:12,end:.infinity)]; let r=geometry(regions:rs,activeRegionID:rs[0].id); XCTAssertEqual(r.count,rs.count); for g in r { XCTAssertNil(g.shadeX); XCTAssertNil(g.shadeWidth) } }
    func testHalfSecondViewportPrecision() { let a=item(start:10.1,end:10.4); let g=geometry(regions:[a],activeRegionID:a.id,start:10,duration:0.5)[0]; assertEqual(g.startX,200); assertEqual(g.endX,800); assertEqual(g.shadeX,200); assertEqual(g.shadeWidth,600) }
    func testCoordinateRoundTripAcrossCertifiedZoomScales() { for d in [180.0,30,15,10,5,1,0.5] { let v=WaveformViewport(start:20,duration:d,width:1000); for x in stride(from:0.0,through:1000.0,by:100.0) { XCTAssertEqual(v.x(forTime:v.time(forX:x)),x,accuracy:accuracy) } } }
    func testSourceOrderingIsPreserved() { let a=item(start:10,end:20),b=item(start:30,end:40),c=item(start:50,end:60),d=item(start:70,end:80); let r=geometry(regions:[a,b,c,d],activeRegionID:c.id,start:0,duration:100); XCTAssertEqual(r.map(\.id),[a.id,b.id,c.id,d.id]) }
    func testGeometryCalculationDoesNotMutateCollection() { let c=AnthemRegionCollection(regions:[item(start:10,end:20),item(start:30,end:40),item(start:50,end:60)]); let original=c; _=geometry(regions:c.regions,activeRegionID:c.first.id,start:0,duration:100); XCTAssertEqual(c,original) }
    func testChangingActiveIdentityDoesNotMutateRegionData() { let c=AnthemRegionCollection(regions:[item(start:10,end:20),item(start:30,end:40),item(start:50,end:60)]); let original=c; for r in c.regions { _=geometry(regions:c.regions,activeRegionID:r.id,start:0,duration:100); XCTAssertEqual(c,original) } }
}
